/* Composer DOM MODEL checks only. No real browser, visual or a11y claim. */
'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const base=fs.readFileSync(path.join(__dirname,'workspace_ui_dom_check.js'),'utf8');
const model={require,__dirname,console,setImmediate,URL,URLSearchParams};vm.createContext(model);
vm.runInContext(base.slice(0,base.indexOf('const tests=[];'))+'\nglobalThis.makeHarness=harness;globalThis.flush=tick;',model);
const {makeHarness,flush:tick}=model;
const tests=[];const test=(name,fn)=>tests.push([name,fn]);
function harness(options={}) {
 let h;
 h=makeHarness({phase:'not_created',...options,post:(body,response)=>{
   if(options.post)return options.post(body,response,h);
   if(!body.action) return response({spec:body.spec,selector:body.spec.selector,task:body.spec.task_id,requester:body.spec.requester,responder:body.spec.requester==='alice'?'bob':'alice',context:'c'.repeat(64),review_digest:'d'.repeat(64),fictional:true,temporary:true});
   if(body.action==='compose_task') { const row={selector:body.spec.selector,task:body.spec.task_id,requester:body.spec.requester,responder:body.spec.requester==='alice'?'bob':'alice',context:'c'.repeat(64),phase:'open'};h.rows.push(row);return response(row); }
   throw Error('Unexpected owner mutation');
 }});
 h.field=id=>h.nodes.findLast(n=>n.id===id);
 h.compose=async()=>{await tick();await h.find('Compose temporary task').click();h.field('composeName').value='books';h.field('composeQuery').value='Fictional public book guides';h.field('composeRequester').value='bob';h.field('composeCount').value='3';};
 h.preview=async()=>{await h.compose();await h.find('Preview exact task').click();};return h;
}
const expected={selector:'custom-books',task_id:'task-books',conversation_id:'conversation-books',requester:'bob',query:'Fictional public book guides',max_items:3};
test('opening composer is read-only with fixed fictional direction and bounded labels',async()=>{const h=harness();await h.compose();assert.equal(h.posts.length,0);assert.match(h.ids.content.textContent,/fictional/);assert.match(h.ids.content.textContent,/eight custom/);assert.equal(h.field('composeQuery').maxLength,512);assert.equal(h.field('composeName').maxLength,48);assert(h.nodes.some(n=>n.tagName==='LABEL'&&n.htmlFor==='composeQuery'));});
test('preview sends exact entered spec without creation or approval',async()=>{const h=harness();await h.preview();assert.deepEqual(JSON.parse(JSON.stringify(h.posts)),[{spec:expected}]);assert.match(h.ids.content.textContent,/Review this temporary task/);assert.match(h.ids.content.textContent,/No response is fabricated/);assert(!h.find('Preview exact task'));assert.equal(h.rows.length,2);});
test('preview neither trims nor silently repairs owner input',async()=>{const h=harness({post:(_,r)=>r({error:'Invalid exact spec'},false)});await h.compose();h.field('composeName').value=' Bad name ';h.field('composeQuery').value=' query ';await h.find('Preview exact task').click();assert.equal(h.posts[0].spec.selector,'custom- Bad name ');assert.equal(h.posts[0].spec.query,' query ');assert.match(h.ids.error.textContent,/Invalid exact spec/);assert(!h.find('Create this reviewed task'));});
test('creation requires exact phrase and shows all reviewed scope and text',async()=>{const h=harness();await h.preview();await h.find('Create this reviewed task').click();for(const text of ['custom-books','task-books','bob','c'.repeat(64),'d'.repeat(64),'Fictional public book guides'])assert(h.ids.dialogBody.textContent.includes(text));await h.confirm('yes');assert.equal(h.posts.length,1);await h.confirm('CREATE TASK');assert.equal(h.posts.length,2);assert.deepEqual(JSON.parse(JSON.stringify(h.posts[1])),{action:'compose_task',spec:expected,review_digest:'d'.repeat(64),confirmation:'CREATE TASK'});assert.equal(h.context.location.hash,'#custom-books/bob/inbox');});
test('cancel and edit discard pending confirmation without creating task',async()=>{const h=harness();await h.preview();await h.find('Create this reviewed task').click();await h.ids.dialogCancel.click();assert.equal(h.posts.length,1);await h.find('Edit as a new review').click();assert(h.find('Preview exact task'));assert.equal(h.posts.length,1);});
test('detached original form cannot alter confirmed snapshot',async()=>{const h=harness();await h.compose();const oldQuery=h.field('composeQuery');await h.find('Preview exact task').click();oldQuery.value='mutated';await h.find('Create this reviewed task').click();await h.confirm('CREATE TASK');assert.equal(h.posts[1].spec.query,expected.query);});
test('navigation away and back fences saved create confirmation',async()=>{const h=harness();await h.preview();await h.find('Create this reviewed task').click();const stale=h.ids.dialogConfirm.onclick;await h.view('garden/alice/inbox');await h.view('compose');h.ids.confirmation.value='CREATE TASK';stale();await tick();assert.equal(h.posts.length,1);});
test('raw hash navigation before event prevents creation',async()=>{const h=harness();await h.preview();await h.find('Create this reviewed task').click();h.context.location.hash='#astronomy/bob/inbox';await h.confirm('CREATE TASK');assert.equal(h.posts.length,1);});
test('lost preview is not reported as committed action and starts no creation',async()=>{const h=harness({post:()=>Promise.reject(Error('lost'))});await h.compose();await h.find('Preview exact task').click();assert.equal(h.posts.length,1);assert.match(h.ids.error.textContent,/preview cannot create a task/);assert(!h.ids.error.textContent.includes('may have committed'));assert(!h.find('Create this reviewed task'));});
test('delayed preview cannot replace a later task view',async()=>{let release;const h=harness({post:()=>new Promise(r=>release=r)});await h.compose();await h.find('Preview exact task').click();await h.view('garden/alice/inbox');release(h.response({spec:expected,selector:'custom-books',task:'task-books',requester:'bob',responder:'alice',context:'c'.repeat(64),review_digest:'d'.repeat(64)}));await tick();assert.match(h.ids.content.textContent,/garden-task/);assert(!h.find('Create this reviewed task'));assert.equal(h.posts.length,1);});
test('lost creation response fences repeat creation and points to catalog inspection',async()=>{const h=harness({post:(body,r)=>!body.action?r({spec:body.spec,selector:'custom-books',task:'task-books',requester:'bob',responder:'alice',context:'c'.repeat(64),review_digest:'d'.repeat(64)}):Promise.reject(Error('lost'))});await h.preview();const create=h.find('Create this reviewed task');await create.click();await h.confirm('CREATE TASK');assert.equal(h.posts.length,2);assert.match(h.ids.error.textContent,/may have committed/);assert(create.disabled);assert(h.find('Inspect task catalog'));await create.click();assert.equal(h.posts.length,2);});
test('duplicate confirmation cannot create twice',async()=>{let release;const h=harness({post:(body,r)=>!body.action?r({spec:body.spec,selector:'custom-books',task:'task-books',requester:'bob',responder:'alice',context:'c'.repeat(64),review_digest:'d'.repeat(64)}):new Promise(resolve=>release=resolve)});await h.preview();await h.find('Create this reviewed task').click();h.ids.confirmation.value='CREATE TASK';h.ids.confirmation.oninput();const click=h.ids.dialogConfirm.onclick;click();click();await tick();assert.equal(h.posts.length,2);release(h.response({selector:'custom-books',task:'task-books',context:'c'.repeat(64),requester:'bob',responder:'alice',phase:'open'}));await tick();assert.equal(h.posts.length,2);});
test('hostile query remains literal text without active elements or links',async()=>{const h=harness();await h.compose();h.field('composeQuery').value='<img src=https://evil.invalid onerror=run()> https://evil.invalid';await h.find('Preview exact task').click();assert(h.ids.content.textContent.includes('<img'));await h.find('Create this reviewed task').click();assert(h.ids.dialogBody.textContent.includes('<img'));assert(!h.nodes.some(n=>['IMG','A','IFRAME','SCRIPT'].includes(n.tagName)));assert.equal(h.posts.length,1);});
test('edit preserves entries but needs a fresh preview token',async()=>{const h=harness();await h.preview();await h.find('Edit as a new review').click();assert.equal(h.field('composeName').value,'books');assert.equal(h.field('composeQuery').value,expected.query);assert.equal(h.field('composeRequester').value,'bob');assert(!h.find('Create this reviewed task'));assert.equal(h.posts.length,1);});
test('waiting for responder stays visible instead of being cleared by navigation',async()=>{const h=makeHarness({post:(_,r)=>r({kind:'awaiting',reason:'Waiting for an explicitly staged and owner-reviewed responder proposal. No result was generated.'})});await tick();await h.view('garden/alice/inbox');await h.find('Prepare next review').click();assert.match(h.ids.content.textContent,/Waiting for a reviewed response/);assert.match(h.ids.content.textContent,/No result was generated/);assert.match(h.ids.content.textContent,/garden-task/);assert.equal(h.posts.length,1);assert(h.find('Back to owner inbox'));});
test('edited task preview rebuilds usable catalog navigation',async()=>{const h=harness();await h.preview();await h.find('Edit as a new review').click();await h.find('garden · not_created').click();assert.equal(h.context.location.hash,'#garden/alice/inbox');assert.equal(h.posts.length,1);});
(async()=>{let failed=0;for(const[name,fn]of tests){try{await fn();console.log('PASS '+name);}catch(e){failed++;console.error('FAIL '+name+'\n'+e.stack);}}console.log(`${tests.length-failed}/${tests.length} composer DOM-model checks passed (not browser tests).`);if(failed)process.exitCode=1;})();
